def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    best = None
    for y in range(H):
        for x in range(W):
            if g[y, x] != bg:
                continue
            hits = []
            total = 0
            ok = True
            for dy, dx in dirs:
                yy, xx, d = y + dy, x + dx, 1
                while 0 <= yy < H and 0 <= xx < W and g[yy, xx] == bg:
                    yy += dy; xx += dx; d += 1
                if not (0 <= yy < H and 0 <= xx < W):
                    ok = False
                    break
                hits.append((yy, xx, int(g[yy, xx]), dy, dx))
                total += d
            if not ok or len(set(h[2] for h in hits)) < 4:
                continue
            if best is None or total < best[0]:
                best = (total, (y, x), hits)
    if best is None:
        return g
    _, (cy, cx), hits = best
    counts = {h[2]: int((g == h[2]).sum()) for h in hits}
    winner = max(hits, key=lambda h: counts[h[2]])
    out = g.copy()
    # remove the losers' tips
    for h in hits:
        if h is not winner:
            out[h[0], h[1]] = bg
    emit(out, "Clear the tips of the three smaller shapes pointing at the centre.")
    # add 3 cells behind the winner, centred on the centre's axis
    col = winner[2]
    _, _, _, dy, dx = winner
    cells = [(yy, xx) for yy, xx in zip(*np.where(g == col))]
    if dy != 0:
        ys = [c[0] for c in cells if c[1] == cx]
        row = min(ys) - 1 if dy < 0 else max(ys) + 1
        for xx in range(cx - 1, cx + 2):
            if 0 <= row < H and 0 <= xx < W:
                out[row, xx] = col
    else:
        xs = [c[1] for c in cells if c[0] == cy]
        colx = min(xs) - 1 if dx < 0 else max(xs) + 1
        for yy in range(cy - 1, cy + 2):
            if 0 <= yy < H and 0 <= colx < W:
                out[yy, colx] = col
    emit(out, "The largest shape absorbs the 3 cells as a line on its far side.")
    return out
